/* From Uiverse.io by absoluteSTrange - Tags: button */
.__UIV_SCOPE__ .button {
  --width: 100px;
  --height: 25px;
  --button-color: #0059ff;
  width: var(--width);
  height: var(--height);
  background: var(--button-color);
  position: relative;
  text-align: center;
  border-radius: 30px;
  font-family: 'Franklin Gothic Medium', 'Arial Narrow', Arial, sans-serif;
  text-decoration: solid;
  transition: background box-shadow 0.3s;
  -webkit-box-shadow: 4px 8px 19px -3px #0059ff;
  box-shadow: 0px 0px 20px -3px #0059ff;
  text-shadow: 0 0 .4em rgb(255, 255, 255);
}

.__UIV_SCOPE__ .button::before {
  position: absolute;
  content: attr(data-tooltip);
  background-color: var(--button-color);
  font-size: 0.9rem;
  color: #111;
}

.__UIV_SCOPE__ .button::after {
  position: absolute;
  content: '';
  width: 0;
  height: 0;
  border: 10px solid transparent;
  border-top-color: var(--button-color);
}

.__UIV_SCOPE__ .button::after,.__UIV_SCOPE__ .button::before {
  opacity: 0;
  visibility: hidden;
  transition: all 0.5s;
}

.__UIV_SCOPE__ .text {
  display: flex;
  align-items: center;
  justify-content: center;
}

.__UIV_SCOPE__ .button-wrapper,.__UIV_SCOPE__ .text,.__UIV_SCOPE__ .icon {
  overflow: hidden;
  position: absolute;
  width: 100%;
  height: 100%;
  left: 0;
  color: #fff;
}

.__UIV_SCOPE__ .text {
  top: 0
}

.__UIV_SCOPE__ .text,.__UIV_SCOPE__ .icon {
  transition: top 0.45s;
}

.__UIV_SCOPE__ .icon {
  color: #fff;
  top: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
}

.__UIV_SCOPE__ .button:hover {
  background: #4586ff;
  box-shadow: 0px 0px 20px -3px #4586ff;
}

.__UIV_SCOPE__ .button:hover .text {
  top: -100%;
}

.__UIV_SCOPE__ .button:hover .icon {
  top: 0;
}
